update public.food_table set aliases = array_append(aliases, 'ダークチョコ') where name = 'ハイカカオチョコ(72%) 1かけ' and not ('ダークチョコ' = any(aliases));
update public.food_table set aliases = array_append(aliases, 'シヨウガ') where name = 'しょうが' and not ('シヨウガ' = any(aliases));
update public.food_table set aliases = array_append(aliases, 'レモンリンゴ酢') where name = 'リンゴ酢炭酸水 1杯' and not ('レモンリンゴ酢' = any(aliases));
update public.food_table set aliases = array_append(aliases, 'ブドウ糖') where name = 'ラムネ菓子 1本' and not ('ブドウ糖' = any(aliases));
update public.food_table set aliases = array_append(aliases, 'inゼリー') where name = 'ゼリー飲料(エネルギー系) 1個' and not ('inゼリー' = any(aliases));
update public.food_table set aliases = array_append(aliases, 'パルテノ') where name = '高たんぱくヨーグルト(パルテノ型) 1個' and not ('パルテノ' = any(aliases));
